  "inlineSchema": "// Prisma schema — mengikuti ERD pada dokumen blueprint (Bagian 5)\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum StatusKeanggotaan {\n  MENUNGGU_VERIFIKASI\n  AKTIF\n  DITOLAK\n  NONAKTIF\n}\n\nenum StatusPendaftaran {\n  PENDING\n  MENUNGGU_PEMBAYARAN\n  TERKONFIRMASI\n  DIBATALKAN\n}\n\nenum StatusPembayaran {\n  PENDING\n  PAID\n  FAILED\n  EXPIRED\n}\n\nenum StatusVerifikasiDokumen {\n  MENUNGGU\n  DISETUJUI\n  DITOLAK\n}\n\nenum StatusJadwal {\n  DIJADWALKAN\n  BERLANGSUNG\n  SELESAI\n  DIBATALKAN\n}\n\nmodel Role {\n  id      String    @id @default(uuid())\n  nama    String    @unique // ADMIN, PEMBINA, ANGGOTA\n  anggota Anggota[]\n\n  @@map(\"role\")\n}\n\nmodel Anggota {\n  id                String            @id @default(uuid())\n  nik               String            @unique\n  namaLengkap       String            @map(\"nama_lengkap\")\n  email             String            @unique\n  noHp              String            @map(\"no_hp\")\n  passwordHash      String            @map(\"password_hash\")\n  roleId            String            @map(\"role_id\")\n  role              Role              @relation(fields: [roleId], references: [id])\n  statusKeanggotaan StatusKeanggotaan @default(MENUNGGU_VERIFIKASI) @map(\"status_keanggotaan\")\n  createdAt         DateTime          @default(now()) @map(\"created_at\")\n  updatedAt         DateTime          @updatedAt @map(\"updated_at\")\n\n  dokumen     Dokumen[]\n  pendaftaran Pendaftaran[]\n  sertifikat  Sertifikat[]\n\n  @@map(\"anggota\")\n}\n\nmodel Dokumen {\n  id               String                  @id @default(uuid())\n  anggotaId        String                  @map(\"anggota_id\")\n  anggota          Anggota                 @relation(fields: [anggotaId], references: [id])\n  jenisDokumen     String                  @map(\"jenis_dokumen\") // KTP, KK, PAS_FOTO, dll\n  urlFile          String                  @map(\"url_file\")\n  statusVerifikasi StatusVerifikasiDokumen @default(MENUNGGU) @map(\"status_verifikasi\")\n  createdAt        DateTime                @default(now()) @map(\"created_at\")\n\n  @@map(\"dokumen\")\n}\n\nmodel KategoriKegiatan {\n  id           String     @id @default(uuid())\n  namaKategori String     @map(\"nama_kategori\")\n  kegiatan     Kegiatan[]\n\n  @@map(\"kategori_kegiatan\")\n}\n\nmodel Kegiatan {\n  id           String           @id @default(uuid())\n  kategoriId   String           @map(\"kategori_id\")\n  kategori     KategoriKegiatan @relation(fields: [kategoriId], references: [id])\n  namaKegiatan String           @map(\"nama_kegiatan\")\n  deskripsi    String\n  jenis        String // TEORI, PRAKTIK, CERAMAH, dll\n  jadwal       JadwalKegiatan[] @relation(\"JadwalKegiatanToKegiatan\")\n\n  @@map(\"kegiatan\")\n}\n\nmodel JadwalKegiatan {\n  id             String        @id @default(uuid())\n  tanggalMulai   DateTime      @map(\"tanggal_mulai\")\n  tanggalSelesai DateTime      @map(\"tanggal_selesai\")\n  kuota          Int\n  kuotaTerisi    Int           @default(0) @map(\"kuota_terisi\")\n  lokasi         String\n  status         StatusJadwal  @default(DIJADWALKAN)\n  kegiatan       Kegiatan[]    @relation(\"JadwalKegiatanToKegiatan\")\n  pendaftaran    Pendaftaran[]\n  sertifikat     Sertifikat[]\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n\n  @@map(\"jadwal_kegiatan\")\n}\n\nmodel Pendaftaran {\n  id            String            @id @default(uuid())\n  anggotaId     String            @map(\"anggota_id\")\n  anggota       Anggota           @relation(fields: [anggotaId], references: [id])\n  jadwalId      String            @map(\"jadwal_id\")\n  jadwal        JadwalKegiatan    @relation(fields: [jadwalId], references: [id])\n  status        StatusPendaftaran @default(PENDING)\n  tanggalDaftar DateTime          @default(now()) @map(\"tanggal_daftar\")\n  pembayaran    Pembayaran?\n\n  @@unique([anggotaId, jadwalId]) // 1 anggota tidak boleh daftar dobel ke jadwal yang sama\n  @@map(\"pendaftaran\")\n}\n\nmodel Pembayaran {\n  id                String           @id @default(uuid())\n  pendaftaranId     String           @unique @map(\"pendaftaran_id\")\n  pendaftaran       Pendaftaran      @relation(fields: [pendaftaranId], references: [id])\n  jumlah            Decimal          @db.Decimal(12, 2)\n  statusBayar       StatusPembayaran @default(PENDING) @map(\"status_bayar\")\n  metode            String?\n  referensiExternal String?          @map(\"referensi_external\") // ID transaksi dari payment gateway\n  tanggalBayar      DateTime?        @map(\"tanggal_bayar\")\n  createdAt         DateTime         @default(now()) @map(\"created_at\")\n\n  @@map(\"pembayaran\")\n}\n\nmodel Sertifikat {\n  id              String         @id @default(uuid())\n  anggotaId       String         @map(\"anggota_id\")\n  anggota         Anggota        @relation(fields: [anggotaId], references: [id])\n  jadwalId        String         @map(\"jadwal_id\")\n  jadwal          JadwalKegiatan @relation(fields: [jadwalId], references: [id])\n  nomorSertifikat String         @unique @map(\"nomor_sertifikat\")\n  urlFile         String         @map(\"url_file\")\n  tanggalTerbit   DateTime       @default(now()) @map(\"tanggal_terbit\")\n\n  @@map(\"sertifikat\")\n}\n\nmodel BalaiProfil {\n  id        String    @id @default(uuid())\n  namaBalai String    @map(\"nama_balai\")\n  sejarah   String\n  visiMisi  String    @map(\"visi_misi\")\n  alamat    String\n  kontak    String\n  galeri    Galeri[]\n  benefit   Benefit[]\n\n  @@map(\"balai_profil\")\n}\n\nmodel Galeri {\n  id         String      @id @default(uuid())\n  balaiId    String      @map(\"balai_id\")\n  balai      BalaiProfil @relation(fields: [balaiId], references: [id])\n  urlGambar  String      @map(\"url_gambar\")\n  keterangan String?\n\n  @@map(\"galeri\")\n}\n\nmodel Benefit {\n  id           String      @id @default(uuid())\n  balaiId      String      @map(\"balai_id\")\n  balai        BalaiProfil @relation(fields: [balaiId], references: [id])\n  judulBenefit String      @map(\"judul_benefit\")\n  deskripsi    String\n\n  @@map(\"benefit\")\n}\n",
